from q import *
from review import RV
from x2_h import *
def V(s):
    o=[]
    for p in s.split('|'):
        e,t=p.split('=');o.append(f'{e};{t};{e[0].upper()+e[1:]}.;{t[0].upper()+t[1:]}.')
    return o
