 [('Forty years of data could be lost.','T','would lose forty years.'),('The project depends on volunteers.','T','Were it not for volunteers.'),('The scientist would exclude communities.','F','involve local communities.')],
 [('“ownership” = ?',['senso de propriedade','dono só','navio'],0,'ownership.'),('“volunteer” = ?',['voluntário','volume','vulto'],0,'volunteers.')],
 G('Revisão: hipótese invertida',['Original (if)','Invertida'],[['If funding were to stop,…','**Were funding to stop,…**'],['If it weren’t for volunteers,…','**Were it not for volunteers,…**'],['If I were in charge,…','**Were I in charge,…**'],['If they felt ownership,…','**Were they to feel ownership,…**']],'Revise: (1) usou **were** (não *was*)? (2) **would** na oração principal? (3) tirou o **if**?'),
 [('___ funding to stop, we would lose forty years of data. (Were)','Were','inversão.',None),('Were it not ___ volunteers, the project would be impossible. (for)','for','were it not for.',None),('Were I in ___ of the budget, I would protect records. (charge)','charge','in charge of.',None),('Were they to feel ownership, they ___ share more data. (would)','would','principal.',None)],
